code_snippets.typescript_frontend_api_call:

// Next.js Frontend - example in a React component or service
import axios from 'axios';

interface Topic {
  title: string;
  description?: string;
}

interface SyllabusParseResponse {
  topics: Topic[];
}

async function parseSyllabus(syllabusText: string, courseId: number): Promise<SyllabusParseResponse> {
  try {
    const response = await axios.post<SyllabusParseResponse>(
      '/api/parse-syllabus', // Proxy to FastAPI backend or direct call
      { syllabus_text: syllabusText, course_id: courseId },
      {
        headers: {
          Authorization: `Bearer ${yourJwtToken}`, // Include user's JWT token
        },
      }
    );
    return response.data;
  } catch (error) {
    console.error('Error parsing syllabus:', error);
    throw error; // Handle this in UI (AC6)
  }
}

